using System;
using System.Linq;
using UnityEngine;
public static class ValidateStreamedMudPersistence {
public static string Main(){if(!Application.isPlaying)throw new Exception("Requires Play");var route=UnityEngine.Object.FindAnyObjectByType<AuthoredForestRoute>();GameObject first=null,second=null;try{first=route.CreateBlock(0,100);var soils=first.GetComponentsInChildren<SoftGroundRuts>().Where(s=>s.enabled&&s.profile!=null).ToArray();var root=soils[0].transform.parent;var ray=new Ray(root.position+Vector3.up*5,Vector3.down);RaycastHit top=default;bool found=false;foreach(var s in soils)if(s.GetComponent<MeshCollider>().Raycast(ray,out var hit,12)&&(!found||hit.point.y>top.point.y)){top=hit;found=true;}if(!found)throw new Exception("Module mud absent");var chosen=top.collider.GetComponent<SoftGroundRuts>();SoftGroundRuts.Contact(top.point,root.forward,.285f,6000,14,1,2);foreach(var s in soils)s.Commit();float before=chosen.DepthAt(top.point);string identity=chosen.persistentId;if(before<.05f)throw new Exception("Module does not dig="+before);UnityEngine.Object.DestroyImmediate(first);first=null;second=route.CreateBlock(0,100);var loaded=second.GetComponentsInChildren<SoftGroundRuts>().First(s=>s.persistentId==identity);float after=loaded.DepthAt(top.point);if(Mathf.Abs(before-after)>.002f)throw new Exception("Streamed track lost before="+before+" after="+after);return "PASS actual authored route block recreation: "+identity+", rut "+before.ToString("F3")+" -> "+after.ToString("F3")+"m; source prefab unchanged.";}finally{if(first!=null)UnityEngine.Object.DestroyImmediate(first);if(second!=null)UnityEngine.Object.DestroyImmediate(second);}}}
